package com.bank.vcs;

public class Commit {
    private final String id;
    private final String message;
    private final boolean revertOf;   // true if this commit inverts another

    public Commit(String id, String message, boolean revertOf) {
        this.id = id;
        this.message = message;
        this.revertOf = revertOf;
    }
    public String getId() { return id; }
    public String getMessage() { return message; }
    public boolean isRevert() { return revertOf; }

    @Override
    public String toString() { return id + " " + message; }
}
