package com.bank.vcs;

import java.util.ArrayList;
import java.util.List;

// A shared branch whose history has already been pulled by other clones.
public class SharedBranch {
    private final String name;
    private final List<Commit> history = new ArrayList<>();
    private int clonesThatPulled = 0;   // teammates who already have this history

    public SharedBranch(String name) { this.name = name; }

    public String getName() { return name; }
    public void append(Commit c) { history.add(c); }
    public List<Commit> getHistory() { return history; }

    // Simulate teammates pulling the current history.
    public void pulledByClones(int n) { clonesThatPulled += n; }
    public boolean isShared() { return clonesThatPulled > 0; }
    public int getClonesThatPulled() { return clonesThatPulled; }
}
