package com.bank.vcs;

import java.util.logging.Logger;

// Resolves a simple two-sided line conflict in the fee-calculation file.
public class ConflictResolver {
    private static final Logger log = Logger.getLogger(ConflictResolver.class.getName());

    // ours vs theirs on the same line; returns the chosen final content.
    public String resolve(String ours, String theirs, String chosen) {
        log.warning("CONFLICT in FeeCalculator.java:");
        log.warning("  <<<<<<< ours:   " + ours);
        log.warning("  =======");
        log.warning("  >>>>>>> theirs: " + theirs);
        log.info(() -> "Resolved by choosing: " + chosen + "  (markers removed, git add, commit)");
        return chosen;
    }
}
