package com.bank.vcs;

import java.util.logging.Logger;

// Guards history edits: revert on shared branches, reset only on private ones.
public class HistoryEditor {
    private static final Logger log = Logger.getLogger(HistoryEditor.class.getName());
    private int seq;

    public HistoryEditor(int startSeq) { this.seq = startSeq; }

    // Attempt a reset + force-push. SAFE only if the branch is NOT shared.
    public boolean resetAndForcePush(SharedBranch branch, String backToId) {
        if (branch.isShared()) {
            log.severe(() -> "REFUSED: reset+force-push on SHARED branch '" + branch.getName()
                    + "' — " + branch.getClonesThatPulled() + " clones already pulled this history. "
                    + "Rewriting it would diverge everyone and risk lost work.");
            return false;
        }
        log.info(() -> "reset --hard " + backToId + " + force-push OK (private branch, no clones)");
        return true;
    }

    // Safe undo on a shared branch: add an inverting commit, history moves FORWARD.
    public Commit revert(SharedBranch branch, Commit bad) {
        Commit inverse = new Commit("c" + (++seq), "Revert \"" + bad.getMessage() + "\"", true);
        branch.append(inverse);
        log.info(() -> "git revert " + bad.getId() + " -> new commit " + inverse.getId()
                + " (bad change inverted, original kept in history, everyone pulls normally)");
        return inverse;
    }
}
