package com.bank.vcs;

import java.util.logging.*;

// Runnable demo: resolve a conflict, refuse reset+force on shared, then revert safely.
public class UndoDemo {
    private static final Logger log = Logger.getLogger(UndoDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — resolve conflict + safely undo a pushed commit");

        // Part 1: resolve a merge conflict on the fee calculator.
        ConflictResolver resolver = new ConflictResolver();
        String finalLine = resolver.resolve(
            "fee = amount.multiply(new BigDecimal(\"0.001\"));",   // ours
            "fee = amount.multiply(new BigDecimal(\"0.0015\"));",  // theirs
            "fee = amount.multiply(new BigDecimal(\"0.0015\")); // compliance-approved rate");

        // Part 2: a bad commit is already on the SHARED development branch.
        SharedBranch dev = new SharedBranch("development");
        dev.append(new Commit("c1", "transfer-service base", false));
        Commit bad = new Commit("c2", "fee calc (BROKEN rounding for SAV2001/CUR3001)", false);
        dev.append(bad);
        dev.pulledByClones(4);   // 4 teammates already pulled c1,c2

        HistoryEditor editor = new HistoryEditor(2);

        // Tempting but WRONG: reset + force-push on a shared branch.
        boolean resetOk = editor.resetAndForcePush(dev, "c1");
        if (!resetOk) {
            // CORRECT: revert — adds an inverting commit, safe for everyone.
            editor.revert(dev, bad);
        }

        log.info("Final shared history (forward-only, audit preserved):");
        for (Commit c : dev.getHistory()) log.info("  " + c);
    }
}
